from pathlib import Path

p=Path('playwright.config.ts')
s=p.read_text()
s=s.replace("testIgnore:[/orientation\\.spec\\.ts/,/orientation-webkit\\.spec\\.ts/]", "testIgnore:[/orientation\\.spec\\.ts/,/orientation-webkit.*\\.spec\\.ts/]")
s=s.replace("{ name:'webkit-mobile-portrait', testMatch:/orientation-webkit\\.spec\\.ts/, grep:/portrait/, use:{...devices['iPhone 14'],viewport:{width:390,height:844}} },", "{ name:'webkit-mobile-portrait', testMatch:/orientation-webkit-portrait\\.spec\\.ts/, use:{...devices['iPhone 14'],viewport:{width:390,height:844}} },")
s=s.replace("{ name:'webkit-mobile-landscape', testMatch:/orientation-webkit\\.spec\\.ts/, grep:/landscape/, use:{...devices['iPhone 14'],viewport:{width:844,height:390}} },", "{ name:'webkit-mobile-landscape', testMatch:/orientation-webkit-landscape\\.spec\\.ts/, use:{...devices['iPhone 14'],viewport:{width:844,height:390}} },")
p.write_text(s)
old=Path('tests/orientation-webkit.spec.ts')
if old.exists(): old.unlink()
common="""import { test, expect } from '@playwright/test';\n"""
Path('tests/orientation-webkit-portrait.spec.ts').write_text(common+"""\ntest('WebKit mobile smoke portrait',async({page},info)=>{ const errors:string[]=[]; page.on('pageerror',e=>errors.push(e.message)); await page.goto('/?perf=1',{waitUntil:'domcontentloaded'}); expect(await page.locator('#orientation').count()).toBe(0); await page.locator('#startBtn').click(); await expect(page.locator('#hud')).toBeVisible(); await expect(page.locator('#touch')).toBeVisible(); expect(await page.evaluate(()=>document.documentElement.dataset.gameOrientation)).toBe('portrait'); await page.locator('#qBtn').dispatchEvent('pointerdown',{pointerId:91,pointerType:'touch',isPrimary:true}); await expect.poll(async()=>Number((await page.evaluate(()=>window.__QS_TEST__.state())).qUses)).toBeGreaterThan(0); expect(errors).toEqual([]); await page.screenshot({path:info.outputPath('webkit-portrait.png')}); });\n""")
Path('tests/orientation-webkit-landscape.spec.ts').write_text(common+"""\ntest('WebKit mobile smoke landscape',async({page},info)=>{ const errors:string[]=[]; page.on('pageerror',e=>errors.push(e.message)); await page.goto('/?perf=1',{waitUntil:'domcontentloaded'}); expect(await page.locator('#orientation').count()).toBe(0); await page.locator('#startBtn').click(); await expect(page.locator('#hud')).toBeVisible(); await expect(page.locator('#touch')).toBeVisible(); expect(await page.evaluate(()=>document.documentElement.dataset.gameOrientation)).toBe('landscape'); await page.locator('#qBtn').dispatchEvent('pointerdown',{pointerId:92,pointerType:'touch',isPrimary:true}); await expect.poll(async()=>Number((await page.evaluate(()=>window.__QS_TEST__.state())).qUses)).toBeGreaterThan(0); expect(errors).toEqual([]); await page.screenshot({path:info.outputPath('webkit-landscape.png')}); });\n""")
print('ORDER-001A WebKit matrix selection fixed')
